\begin{theorem}[Two-Sided Quasi-Isometric Morita Resource Interleaving]\label{ch01:thm:morita-resource-interleaving}%
\uses{ch01:def:operational-currencies,ch01:claim:abramsky-arboreal-coalgebra-numbers}%
Let $(I, J; \eta, \varepsilon)$ be a syntactic pretopos bi-interpretation between first-order theories $T_1$ and $T_2$~\cite{johnstone2002} whose induced quotient/finite-product definitions have forward quantifier-rank distortion $(a, b) \in \mathbb{N}_{\ge 1} \times \mathbb{N}$ and backward distortion $(a', b') \in \mathbb{N}_{\ge 1} \times \mathbb{N}$ relative to the Ehrenfeucht--Fra\"iss\'e game-comonad towers {{sym:ef-comonad}} of {{ref:ch01:claim:abramsky-arboreal-coalgebra-numbers}}. Then for all $k, m \in \mathbb{N}$:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Two-Sided Interleaving:}
  \[
    (\equiv_{a k + b}^{\mathbb{E}, T_1}) \;\subseteq\; I^*(\equiv_k^{\mathbb{E}, T_2}), \qquad
    I^*(\equiv_{a' m + b'}^{\mathbb{E}, T_2}) \;\subseteq\; (\equiv_m^{\mathbb{E}, T_1}).
  \]
  \item \textbf{Floor-Bound Corollary:} For every $k \ge b'$, $I^*(\equiv_k^{\mathbb{E}, T_2}) \subseteq (\equiv_{\lfloor (k - b')/a' \rfloor}^{\mathbb{E}, T_1})$.
  \item \textbf{Exact $k = \infty$ Invariance:} $\bigcap_{k \in \mathbb{N}} \equiv_k^{\mathbb{E}, T_1} \;=\; I^*\!\Bigl(\bigcap_{k \in \mathbb{N}} \equiv_k^{\mathbb{E}, T_2}\Bigr)$.
\end{enumerate}
\end{theorem}
\begin{proof}
Each definable sort and relation of $T_2$ translates along $I$ into finite tuples and formulas over $T_1$ of bounded quantifier-rank overhead $(a, b)$, so any Spoiler $k$-round strategy between $I(M_1)$ and $I(M_2)$ unfolds to an $(ak + b)$-round Spoiler strategy between $M_1$ and $M_2$; contrapositively, $M_1 \equiv_{ak+b}^{\mathbb{E}, T_1} M_2 \implies I(M_1) \equiv_k^{\mathbb{E}, T_2} I(M_2)$. Symmetrically, translating along $J$ with backward distortion $(a', b')$ gives $I(M_1) \equiv_{a'm+b'}^{\mathbb{E}, T_2} I(M_2) \implies J(I(M_1)) \equiv_m^{\mathbb{E}, T_1} J(I(M_2))$, and the unit isomorphism $\eta_{M} : M \cong J(I(M))$ transfers this to $M_1 \equiv_m^{\mathbb{E}, T_1} M_2$. For $k \ge b'$, setting $m := \lfloor (k - b')/a' \rfloor$ yields $a' m + b' \le k$, so antitonicity of the descending filtration gives $I^*(\equiv_k^{\mathbb{E}, T_2}) \subseteq I^*(\equiv_{a' m + b'}^{\mathbb{E}, T_2}) \subseteq (\equiv_m^{\mathbb{E}, T_1})$. Taking the intersection over all $k \in \mathbb{N}$ yields exact $k = \infty$ Morita invariance~\cite{abramsky2022,abramsky_shah2021}.
\end{proof}

\begin{counterexample}[Russell's Socks Touchstone: Levelwise Morita Failure]\label{ch01:cex:russells-socks-levelwise-morita-failure}%
\uses{ch01:thm:morita-resource-interleaving}%
Consider the single-sorted theory $T_1$ of paired socks $(X, E, D)$ (pair equivalence $E$, irreflexive symmetric mismatch relation $D \subseteq E \setminus \Delta_X$) and its Morita-equivalent quotient presentation $T_2$ adjoining the pair sort $Q = X/E$, projection graph $G_\pi(x, q)$, and definable predicate $\mathrm{Mis}(q) \iff \exists x, y,\; G_\pi(x,q) \wedge G_\pi(y,q) \wedge D(x,y)$. Constructively without axioms (stratum \textbf{Emerald}):
