\begin{theorem}[Three-Way Model-Space Failure of Naive Pullback Along {{sym:piset}}]\label{ch02:thm:three-way-pullback-failure}%
\uses{ch02:def:gb0-model-category}%
Along a proper $\mathcal{L}_\in$-elementary or $\in$- and pair-preserving embedding $f : M_{\mathrm{fin}} \hookrightarrow M_{\mathrm{full}}$ in {{sym:mod-gb0}}, naive trace pullback $f^*\mathcal{D} := \{f^{-1}[D] \subseteq |M_{\mathrm{fin}}| \mid D \in \mathcal{D}\}$ fails to yield Cartesian lifts for {{sym:piset}} along three independent obstructions~\cite{godel1940}:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Subclass Separation Leak:} For $M_{\mathrm{fin}}$ supporting finite/tail-constant sets over $\mathbb{N}$ and $M_{\mathrm{full}}$ adjoining all $A \subseteq \mathbb{N}$, the definable class $\mathrm{even} \in {{sym:def-functor}}(M_{\mathrm{full}})$ pulls back onto a bounded subclass $f^{-1}[\mathrm{even}] \subseteq \omega \in M_{\mathrm{fin}}$ having no representing set in $M_{\mathrm{fin}}$.
  \item \textbf{G\"odel G4 Domain-Projection Failure:} Taking an external witness $y_0 \in M_{\mathrm{full}} \setminus \mathrm{range}(f)$ and $D := \{(f(x_0), y_0)\} \in {{sym:def-functor}}(M_{\mathrm{full}})$, we have $\mathrm{dom}^{M_{\mathrm{fin}}}(f^{-1}[D]) = \emptyset \neq \{x_0\} = f^{-1}[\mathrm{dom}^{M_{\mathrm{full}}}(D)]$.
  \item \textbf{Preimage Collapse (Non-Uniqueness):} The distinct classes $D_1 := \emptyset \neq \{y_0\} =: D_2$ in $\mathcal{D}$ satisfy $f^{-1}[D_1] = \emptyset = f^{-1}[D_2]$, blocking unique Cartesian mediating lifts.
\end{enumerate}
\end{theorem}
\begin{proof}
Construct $M_{\mathrm{fin}}$ with atom carrier $\mathbb{N}$, tail-constant finite-override sets $S$, and inductive pairs $\langle x, y \rangle$, and take $\mathcal{C}_{\mathrm{fin}}$ to be all finitely supported predicates invariant under tail atom permutations above a finite bound $N$. Then $(M_{\mathrm{fin}}, \mathcal{C}_{\mathrm{fin}}) \models {{sym:gb0}}$: closure under G\"odel operations \textbf{G1--G8} follows by transporting witness pairs under tail involutions, while Subclass Separation holds by overriding $[0, N)$ and setting the tail value at $N$. Embedding $M_{\mathrm{fin}} \hookrightarrow M_{\mathrm{full}}$ over $\mathbb{N}$ leaves $y_0 := \mathrm{even}$ outside $\mathrm{range}(f)$ and non-tail-constant above every finite override bound, giving~(1); evaluating $f^{-1}[D]$ at $y_0 \notin \mathrm{range}(f)$ yields~(2) and~(3).
\end{proof}

