\begin{proposition}[Unbundling Limitation of Size Over {{sym:gb0}} and $2\times 2$ Independence]\label{ch02:prop:los-unbundling-independence}%
\uses{vol1:prop:los-smuggles-gc,ch02:def:gb0-model-category}%
