\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item Von Neumann's Limitation of Size ($\mathsf{LoS}$: a class $C$ fails to be small iff $C$ surjects onto $V$) is strictly equivalent to $(\mathrm{Rep} \wedge \mathsf{GC})$, so ${{sym:gb0}} + \mathsf{LoS} = {{sym:nbg}}$ smuggles Global Choice across Choice-free bases.
  \item Over {{sym:gb0}}, $\mathrm{Rep}$ and $\mathsf{GC}$ are mutually independent: $(\mathrm{Rep} \wedge \neg\mathsf{GC} \wedge \neg\mathsf{LoS})$ holds in tail Easton models $(M, {{sym:def-functor}}(M))$~\cite{easton1970,felgner1971}, while $(\mathsf{GC} \wedge \neg\mathrm{Rep} \wedge \neg\mathsf{LoS})$ holds in G\"odel's $(L_{\omega_\omega^L}, {{sym:def-functor}}(L_{\omega_\omega^L}))$~\cite{godel1940}.
\end{enumerate}
\end{proposition}
\begin{proof}
For $(\mathsf{LoS} \implies \mathrm{Rep} \wedge \mathsf{GC})$, Burali--Forti gives $\mathrm{Ord} \notin \mathcal{S}$, so $\mathsf{LoS}$ provides a surjection $p : \mathrm{Ord} \twoheadrightarrow V$ whose minimal-preimage selector yields $\mathsf{GC}$; for $\mathrm{Rep}$, if $F[A] \notin \mathcal{S}$ for small $A$, composing $\mathsf{LoS}$'s surjection $q : F[A] \twoheadrightarrow V$ with $F$ yields $h : A \twoheadrightarrow V$, refuting Russell--Cantor diagonalization on $D = \{a \in A \mid a \notin h(a)\}$. Conversely, under $\mathrm{Rep} + \mathsf{GC}$ Foundation stratifies $V = \bigcup_{\alpha} V_\alpha$, giving $\Phi : V \xrightarrow{\sim} \mathrm{Ord}$, and every proper class $C$ maps bijectively onto $\mathrm{Ord}$ via initial-segment order types (without $\mathsf{ETR}_{\mathrm{Ord}}$), establishing $\mathsf{LoS}$. For independence, Easton tail forcing~\cite{easton1970} yields $\mathrm{Rep} + \neg\mathsf{GC}$, whereas in $L_{\omega_\omega^L}$ G\"odel condensation~\cite{godel1940} verifies Power Set and $\mathsf{Z}$ alongside the global $<_L$-well-order ($\mathsf{GC}$), while the countable cofinal sequence $\{\omega_n^L\}_{n < \omega}$ admits no surjection onto $L_{\omega_\omega^L}$, refuting $\mathrm{Rep}$ and $\mathsf{LoS}$.
\end{proof}

\begin{theorem}[Williams's Fixed-Set Universality and Independent-Generator Fiber Embedding]\label{ch02:thm:williams-fixed-set-kaleidoscope}%
\uses{ch02:def:gb0-model-category,ch02:thm:def-left-adjoint-coreflection,ch02:claim:easton-hod-unsplit-card}%
Let $M \models \mathsf{ZFC}$ be any countable model, held completely rigid via $\mathrm{id}_M$.
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Fixed-Set Universality (Williams~2018~\cite{williams2018}):} The vertical fiber poset ${{sym:piset}}^{-1}(M)$ of ${{sym:gbc}}$-realizations $(M, \mathcal{C})$ ordered by class inclusion $\mathcal{C} \subseteq \mathcal{C}'$ embeds every countable partial order~\cite{felgner1971}.
  \item \textbf{Independent-Generator Order Embedding:} For any partial order $(P, \le)$ and any algebraically independent generator family $(G_p)_{p \in P}$ with monotone class closure $\mathrm{cl}$ over a fixed base $M$, the principal-ideal map $p \mapsto \mathcal{C}_{\downarrow p} := \mathrm{cl}(\{G_q \mid q \le p\})$ is a strict order embedding $(P, \le) \hookrightarrow_o {{sym:piset}}^{-1}(M)$ holding $M$ identically rigid.
\end{enumerate}
\end{theorem}
\begin{proof}
For~(2), monotonicity $p \le q \implies \mathcal{C}_{\downarrow p} \subseteq \mathcal{C}_{\downarrow q}$ is immediate from monotonicity of $\mathrm{cl}$; conversely, if $\mathcal{C}_{\downarrow p} \subseteq \mathcal{C}_{\downarrow q}$ then $G_p \in \mathcal{C}_{\downarrow q}$, and algebraic independence forces $p \le q$, while antisymmetry yields injectivity. To realize~(1) over countable $M \models \mathsf{ZFC}$, Williams~\cite[Ch.~2--3]{williams2018} constructs by product class forcing a countable mutually generic family of proper classes $(G_p)_{p \in P}$ preserving ${{sym:gbc}}$ and remaining independent under class-definable combinations.
\end{proof}

